new = chg = 0
def put(rel, data, binary):
    global new, chg
    p = os.path.join(root, rel)
    cur = open(p, "rb").read() if os.path.exists(p) else None
    if cur == data: return
    if cur is not None:
        os.makedirs(os.path.dirname(os.path.join(bk, rel)), exist_ok=True); shutil.copy2(p, os.path.join(bk, rel)); chg += 1
    else: new += 1
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, "wb").write(data)
for rel, text in DATA["files"].items(): put(rel, text.encode("utf-8"), False)
for rel, b in DATA["bin"].items(): put(rel, base64.b64decode(b), True)
print(f"wrote {new} new and {chg} changed files" + (f" (old copies in {os.path.basename(bk)})" if chg else ""))
ok = all(os.path.exists(os.path.join(root, r)) for r in list(DATA["files"]) + ["frontend/public/logo-wl.png"])
print("  OK    animated logo files in place" if ok else "  FAIL  some files missing")
print("DONE. Next:  cd frontend && npm run build   (then commit, push and redeploy)")
